"""Repeatable transformations: python code generated by the CLT-AI Agent ("code generation mode").

A transformation is python source defining:

    def transform(clt, row: dict) -> dict:
        ...

`clt` is a CLT-AI client (cloudlanguagetools.cltai.create_client), `row` maps input field / column
names to values, and the returned dict maps output field names to values (str, or SoundResult for
audio). The Transformation model is meant to be stored (model_dump_json) and re-run over many rows.
Executing the code is not sandboxed yet.
"""

import inspect
import traceback
from typing import Any, Callable, Dict, Iterable, List

import pydantic
from pydantic import Field

import cloudlanguagetools.cltai as cltai
from cloudlanguagetools.cltai.types import CltAPIVersion, CltAIError

TRANSFORM_FUNCTION_NAME = 'transform'


def build_namespace() -> Dict[str, Any]:
    """globals available to generated code, in addition to whatever it imports"""
    namespace = {'__name__': 'cltai_transformation', 'cltai': cltai}
    for name in cltai.__all__:
        namespace[name] = getattr(cltai, name)
    return namespace


def compile_transform(code: str) -> Callable:
    """compile generated code and return its transform(clt, row) function. Raises CltAIError."""
    namespace = build_namespace()
    try:
        exec(compile(code, '<cltai_transformation>', 'exec'), namespace)
    except Exception as e:
        raise CltAIError(f'transformation code failed to load: {type(e).__name__}: {e}\n{traceback.format_exc(limit=3)}') from e
    function = namespace.get(TRANSFORM_FUNCTION_NAME)
    if not callable(function):
        raise CltAIError(f'transformation code must define a function {TRANSFORM_FUNCTION_NAME}(clt, row) -> dict')
    parameters = list(inspect.signature(function).parameters)
    if len(parameters) != 2:
        raise CltAIError(f'{TRANSFORM_FUNCTION_NAME} must take exactly two parameters (clt, row), got ({", ".join(parameters)})')
    return function


class Transformation(pydantic.BaseModel):
    """a stored, repeatable transformation generated by the CLT-AI Agent"""
    api_version: CltAPIVersion = Field(description='CLT-AI API version the code was written against')
    instruction: str = Field(description='the user instruction this transformation implements')
    description: str = Field(description='short human readable description of what the transformation does')
    input_fields: List[str] = Field(description='row fields read by the transformation')
    output_fields: List[str] = Field(description='row fields written by the transformation')
    code: str = Field(description='python source defining transform(clt, row) -> dict')

    def compile(self) -> Callable:
        return compile_transform(self.code)

    def _check_client(self, clt):
        if clt.api_version != self.api_version:
            raise CltAIError(f'transformation was written for CLT-AI API {self.api_version.value}, '
                             f'client is {clt.api_version.value}: create the client with create_client(CltAPIVersion.{self.api_version.value})')

    def _check_output(self, output) -> Dict[str, Any]:
        if not isinstance(output, dict):
            raise CltAIError(f'{TRANSFORM_FUNCTION_NAME} must return a dict, got {type(output).__name__}')
        unexpected = [k for k in output if k not in self.output_fields]
        if len(unexpected) > 0:
            raise CltAIError(f'{TRANSFORM_FUNCTION_NAME} returned unexpected fields {unexpected}, declared output_fields: {self.output_fields}')
        return output

    def run(self, clt, row: Dict[str, Any]) -> Dict[str, Any]:
        """apply the transformation to one row"""
        self._check_client(clt)
        return self._check_output(self.compile()(clt, row))

    def run_rows(self, clt, rows: Iterable[Dict[str, Any]], stop_on_error: bool = False) -> List[Dict[str, Any] | Exception]:
        """apply the transformation to many rows. Returns one output dict per row, or the exception
        raised for that row when stop_on_error is False"""
        self._check_client(clt)
        function = self.compile()
        results = []
        for row in rows:
            try:
                results.append(self._check_output(function(clt, row)))
            except Exception as e:
                if stop_on_error:
                    raise
                results.append(e)
        return results
